        {"id": "lesson_09_e26", "type": "multiple_choice", "prompt": "In the short dialogue Youoko was born in 1973. Which reading is that year?", "choices": ["senkyuu hyaku nanajuusan nen", "senkyuu hyaku nijuusan nen", "nisen nanajuusan nen", "senkyuu hyaku nanajuusan gatsu"], "answerIndex": 0, "explanation": "1973 = senkyuu hyaku nanajuusan nen. Note がつ is for months, not years.", "source": "lesson_09 p.195", "verified": True, "skill": "grammar"},
