        {"id": "lesson_09_q6", "type": "multiple_choice", "prompt": "A complete date in Japanese starts with...", "choices": ["the year", "the day of the month", "the month", "the day of the week"], "answerIndex": 0, "explanation": "YEAR + MONTH + DAY OF MONTH — largest span to smallest.", "source": "lesson_09 p.185", "verified": True, "skill": "grammar"},
